#!/usr/bin/env python3
import hashlib, html, io, json, runpy, time, urllib.parse, urllib.request
from pathlib import Path
from PIL import Image
base=runpy.run_path(str(Path(__file__).with_name('publish_recipe_20260825_1000.py')),run_name='recipe_base')
TITLE='Pão de Cenoura Caseiro para Bebê: Receita Macia sem Açúcar'; SLUG_KEY='pao-cenoura-caseiro-bebe'; CLUSTER='Cluster 3 — Café da manhã e lanches sem açúcar'; KEYWORD='pão de cenoura caseiro para bebê'
MARKER=base['MARKER']; BLOG_ID=base['BLOG_ID']; COVER_DIR=base['COVER_DIR']; RAW_BASE=base['RAW_BASE']; LOG_PATH=base['LOG_PATH']; RESULT_PATH=base['RESULT_PATH']; W,H=1200,630

def generate_cover(path):
 p="Photorealistic horizontal food photograph of homemade Brazilian carrot bread for a baby-friendly recipe, a small soft golden-orange loaf sliced to show a tender moist crumb with subtle carrot flecks, on a light ceramic plate, a small whole carrot and a few oat flakes nearby, bright natural morning window light, pale wood breakfast table, neutral linen, realistic home food photography, three-quarter close view, natural imperfections. No sugar, frosting, honey, syrup, chocolate, baby, child, people, hands, text, logo, watermark, packaging, collage, illustration or cartoon."
 enc=urllib.parse.quote(p,safe=''); seed=int(hashlib.sha256(TITLE.encode()).hexdigest()[:12],16)%2147483647; last=None
 for a in range(8):
  try:
   u=f'https://image.pollinations.ai/prompt/{enc}?width={W}&height={H}&model=flux&nologo=true&safe=true&enhance=true&seed={seed+a*10007}'; req=urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0 (compatible; ReceitasParaPequenos/3.0)','Accept':'image/*'})
   with urllib.request.urlopen(req,timeout=240) as r: raw=r.read()
   if len(raw)<15000: raise RuntimeError('small image response')
   im=Image.open(io.BytesIO(raw)).convert('RGB'); tr=W/H; cr=im.width/im.height
   if cr>tr: nw=int(im.height*tr); x=(im.width-nw)//2; im=im.crop((x,0,x+nw,im.height))
   elif cr<tr: nh=int(im.width/tr); y=(im.height-nh)//2; im=im.crop((0,y,im.width,y+nh))
   im=im.resize((W,H),Image.Resampling.LANCZOS); path.parent.mkdir(parents=True,exist_ok=True); im.save(path,'JPEG',quality=92,optimize=True,progressive=True); return
  except Exception as e: last=e; time.sleep(min(10*(a+1),45))
 raise RuntimeError(f'cover generation failed: {last}')

def article(cover):
 schema={'@context':'https://schema.org','@type':'Recipe','name':TITLE,'image':[cover],'author':{'@type':'Organization','name':'Equipe Editorial do Receitas Para Pequenos'},'description':'Pão caseiro macio de cenoura, sem açúcar adicionado, para variar o café da manhã ou lanche na alimentação complementar.','recipeCategory':'Café da manhã e lanche','recipeCuisine':'Brasileira','keywords':KEYWORD+', pão para bebê, lanche sem açúcar','recipeYield':'1 pão pequeno','recipeIngredient':['1 cenoura pequena cozida e amassada','1 ovo','1 xícara de farinha de trigo','1/4 de xícara de água','1 colher (chá) de fermento químico em pó'],'recipeInstructions':[{'@type':'HowToStep','text':'Misture a cenoura amassada, o ovo e a água.'},{'@type':'HowToStep','text':'Incorpore a farinha até formar massa espessa.'},{'@type':'HowToStep','text':'Misture o fermento e asse em forma pequena até o centro estar completamente cozido.'}]}
 sj=json.dumps(schema,ensure_ascii=False).replace('</','<\\/'); alt=html.escape(TITLE,quote=True)
 return f"""{MARKER}<div class='separator' style='clear:both;margin:0 0 24px;text-align:center'><img alt='{alt}' data-original-height='630' data-original-width='1200' src='{cover}' style='border-radius:14px;height:auto;max-width:100%;width:1200px'/></div><p><strong>Por Equipe Editorial do Receitas Para Pequenos</strong></p><p>Este pão de cenoura caseiro é uma opção macia e sem açúcar adicionado para variar o café da manhã ou o lanche. A cenoura cozida entra na própria massa e ajuda a deixá-la úmida e fácil de cortar.</p><p><strong>Atenção:</strong> adapte tamanho, formato e textura às habilidades da criança e ofereça sempre com ela sentada e supervisionada. Alergias, dificuldades de mastigação/deglutição e necessidades especiais exigem orientação profissional individualizada.</p><h2>Ingredientes</h2><ul><li>1 cenoura pequena, cozida até ficar bem macia e amassada</li><li>1 ovo</li><li>1 xícara de farinha de trigo</li><li>1/4 de xícara de água, aproximadamente</li><li>1 colher (chá) de fermento químico em pó</li></ul><h2>Modo de preparo</h2><ol><li>Preaqueça o forno a 180 °C e prepare uma forma pequena.</li><li>Misture a cenoura amassada com o ovo e parte da água.</li><li>Acrescente a farinha aos poucos. A massa deve ficar espessa, mas úmida; ajuste com pequenas quantidades da água restante se necessário.</li><li>Incorpore o fermento delicadamente.</li><li>Coloque na forma e asse até crescer, firmar e ficar completamente cozido no centro. Confira com um palito e deixe amornar antes de cortar.</li></ol><h2>Como deve ficar a textura</h2><p>O miolo deve ficar macio, úmido e sem partes cruas ou crosta excessivamente dura. A consistência e o formato oferecidos devem acompanhar as habilidades da criança, evoluindo gradualmente durante a alimentação complementar.</p><h2>Como servir e adaptar</h2><p>Sirva sem coberturas açucaradas. Para quem já consegue pegar alimentos macios, corte em tiras ou pedaços adequados às habilidades individuais. Se necessário, amasse o miolo com um garfo para obter uma textura mais fácil de manejar.</p><h2>Por que a receita não leva açúcar?</h2><p>O Ministério da Saúde orienta não oferecer açúcar nem preparações com açúcar para crianças menores de 2 anos. A cenoura contribui com sabor próprio, sem necessidade de adoçar a massa.</p><h2>Substituições culinárias</h2><p>A quantidade de água pode variar conforme a umidade da cenoura e a farinha. Não faça substituições de ovo ou trigo por motivo de alergia sem orientação de profissional habilitado, pois isso exige avaliação individual.</p><h2>Perguntas frequentes</h2><h3>Posso usar cenoura crua ralada?</h3><p>Nesta versão, prefira a cenoura cozida e bem amassada, que se incorpora melhor à massa e favorece um miolo mais uniforme.</p><h3>Precisa colocar açúcar ou mel?</h3><p>Não. A receita não precisa de açúcar, adoçante nem mel.</p><h3>Como saber se o pão está assado?</h3><p>O centro deve estar firme e sem massa crua. Espete um palito na parte central; ele deve sair sem massa úmida aderida.</p><h2>Receitas relacionadas</h2><ul><li><a href='https://www.receitasparapequenos.site/2026/08/muffin-de-maca-e-aveia-sem-acucar-para.html'>Muffin de Maçã e Aveia sem Açúcar para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/panqueca-de-pera-e-aveia-sem-acucar.html'>Panqueca de Pera e Aveia sem Açúcar para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/paozinho-caseiro-macio-sem-acucar-para.html'>Pãozinho Caseiro Macio sem Açúcar para Bebê</a></li></ul><h2>Referências oficiais</h2><ul><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/primeira-infancia/alimentacao-saudavel' rel='nofollow'>Ministério da Saúde — Alimentação saudável na primeira infância</a></li><li><a href='https://www.gov.br/saude/pt-br/composicao/saps/promocao-da-saude/guias-alimentares/publicacoes/guia_da_crianca_2019.pdf/view' rel='nofollow'>Ministério da Saúde — Guia Alimentar para Crianças Brasileiras Menores de 2 Anos</a></li></ul><script type='application/ld+json'>{sj}</script>"""

def main():
 tok=base['token'](); posts=base['list_posts'](tok)
 for p in posts:
  t=(p.get('title') or '').casefold()
  if t==TITLE.casefold() or ('pão' in t and 'cenoura' in t and 'caseiro' in t):
   RESULT_PATH.write_text(f'outcome=skipped_duplicate\ntitle={p.get("title","")}\nurl={p.get("url","")}\n',encoding='utf-8'); base['git_commit_push']([RESULT_PATH],'Record duplicate prevention for carrot bread'); return
 suffix=hashlib.sha1(TITLE.encode()).hexdigest()[:10]; cp=COVER_DIR/f'{SLUG_KEY}-{suffix}.jpg'; cu=f'{RAW_BASE}/{cp.name}'
 if not cp.exists(): generate_cover(cp); base['git_commit_push']([cp],'Add unique AI food photo for carrot bread'); time.sleep(8)
 content=article(cu)
 if MARKER not in content or cu not in content: raise RuntimeError('cover verification failed before publish')
 created=base['api'](tok,'POST',f'/blogs/{BLOG_ID}/posts',{'isDraft':'false','fetchBody':'true'},{'kind':'blogger#post','blog':{'id':BLOG_ID},'title':TITLE,'content':content,'labels':['Alimentação complementar','Café da manhã','Lanche','Pão','Sem açúcar']}); pid=str(created.get('id','')); url=created.get('url','')
 if not pid: raise RuntimeError('Blogger did not return post id')
 vc=(base['api'](tok,'GET',f'/blogs/{BLOG_ID}/posts/{pid}',{'view':'ADMIN'}).get('content') or '')
 if MARKER not in vc or cu not in vc: raise RuntimeError('live Blogger post failed cover verification')
 log=base['load_log'](); log.append({'published_at':created.get('published'),'title':TITLE,'url':url,'post_id':pid,'cluster':CLUSTER,'keyword':KEYWORD,'cover_url':cu,'marker':MARKER}); LOG_PATH.write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); RESULT_PATH.write_text('outcome=success\n'+f'title={TITLE}\nurl={url}\npost_id={pid}\ncluster={CLUSTER}\ncover_url={cu}\nmarker_verified=true\n',encoding='utf-8'); base['git_commit_push']([LOG_PATH,RESULT_PATH],'Record published carrot bread recipe')
if __name__=='__main__': main()
